package got.world.genlayer; public class GOTGenLayerBeach extends GOTGenLayer {private final int oceanId,beachId;public GOTGenLayerBeach(long s,GOTGenLayer p,int ocean,int beach){super(s);gotParent=p;oceanId=ocean;beachId=beach;}public int[] getInts(int x,int z,int w,int h){int[] p=gotParent.getInts(x-1,z-1,w+2,h+2),o=new int[w*h];for(int dz=0;dz<h;dz++)for(int dx=0;dx<w;dx++){int c=p[dx+1+(dz+1)*(w+2)];if(c!=oceanId&&(p[dx+(dz+1)*(w+2)]==oceanId||p[dx+2+(dz+1)*(w+2)]==oceanId||p[dx+1+dz*(w+2)]==oceanId||p[dx+1+(dz+2)*(w+2)]==oceanId))c=beachId;o[dx+dz*w]=c;}return o;}}